<script setup lang="ts">definePageMeta({middleware:'auth'});const route=useRoute();const {request}=useApi();const {user}=useAuth();const {data,error,refresh}=await useAsyncData(`order-${route.params.id}`,()=>request<any>(`/orders/${route.params.id}`));const reason=ref('');async function action(a:string){await request(`/orders/${route.params.id}/${a}`,{method:'POST',...(a==='cancel'?{body:{cancel_reason:reason.value}}:{})});await refresh()}</script><template><section v-if="data?.data"><h1 class="text-2xl font-bold">{{data.data.order_number}}</h1><p class="my-2">Status: {{data.data.status}}</p><ol class="flex gap-4 my-5 text-sm"><li v-for="s in ['PENDING','PAID','SHIPPED','COMPLETED']" :class="data.data.status===s?'font-bold text-blue-700':''">{{s}}</li></ol><table class="w-full bg-white"><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr><tr v-for="i in data.data.items"><td>{{i.product?.product_name}}</td><td>{{i.quantity}}</td><td>{{i.unit_price}}</td><td>{{i.subtotal}}</td></tr></table><h2 class="font-bold mt-4">Total: {{data.data.total_amount}}</h2><div class="flex gap-2 mt-5"><button v-if="data.data.status==='PENDING'" @click="action('pay')">Mark Paid</button><button v-if="user?.role==='admin'&&data.data.status==='PAID'" @click="action('ship')">Ship</button><button v-if="user?.role==='admin'&&data.data.status==='SHIPPED'" @click="action('complete')">Complete</button><template v-if="user?.role==='admin'&&['PENDING','PAID'].includes(data.data.status)"><input v-model="reason" placeholder="Cancel reason" class="border p-2"><button @click="action('cancel')">Cancel</button></template><a :href="`http://localhost:8000/api/orders/${route.params.id}/invoice`" target="_blank">Invoice</a></div></section><p v-else-if="error">Order not found.</p></template>
